"use client";

const MOCK_LEADS = [
  {
    name: "Kitchen remodel - Encino",
    source: "Website form",
    status: "New",
    createdAt: "2m ago",
  },
  {
    name: "Roof repair - Calabasas",
    source: "Facebook Ads",
    status: "SMS sent",
    createdAt: "7m ago",
  },
  {
    name: "Pool build - Thousand Oaks",
    source: "Landing page",
    status: "Awaiting reply",
    createdAt: "12m ago",
  },
  {
    name: "Landscaping - Woodland Hills",
    source: "Google Ads",
    status: "Booked",
    createdAt: "19m ago",
  },
];

export default function LeadsPage() {
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-2">
        <div>
          <h1 className="text-lg font-semibold">Leads</h1>
          <p className="text-sm text-white/35">
            All leads synced from forms, ads and SMS.
          </p>
        </div>
        <div className="flex gap-2">
          <button className="rounded-[10px] bg-white/5 px-3 py-1.5 text-sm text-white/70 hover:bg-white/10">
            Filter
          </button>
          <button className="rounded-[10px] bg-white px-3 py-1.5 text-sm text-black font-medium hover:bg-white/90">
            + Add lead
          </button>
        </div>
      </div>

      <div className="rounded-[10px] border border-white/5 bg-white/1 p-3">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-white/30 border-b border-white/5">
                <th className="py-2">Lead</th>
                <th className="py-2">Source</th>
                <th className="py-2">Status</th>
                <th className="py-2 text-right">Created</th>
              </tr>
            </thead>
            <tbody>
              {MOCK_LEADS.map((lead) => (
                <tr key={lead.name} className="border-b border-white/5/10">
                  <td className="py-2">{lead.name}</td>
                  <td className="py-2 text-white/40">{lead.source}</td>
                  <td className="py-2">
                    <span
                      className={`inline-flex rounded-[10px] px-2 py-0.5 text-xs ${
                        lead.status === "Booked"
                          ? "bg-amber-500/10 text-amber-200"
                          : lead.status === "New"
                          ? "bg-emerald-500/10 text-emerald-200"
                          : "bg-white/5 text-white/40"
                      }`}
                    >
                      {lead.status}
                    </span>
                  </td>
                  <td className="py-2 text-right text-xs text-white/30">
                    {lead.createdAt}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p className="mt-3 text-xs text-white/30">
          Source: <code>/tenants/{`{tenantId}`}/leads</code>
        </p>
      </div>
    </div>
  );
}
